import type { Meta, StoryObj } from "@storybook/vue3";
import { KozmosTag } from "../../index";

/**
 * Vue's Tag: the stories React's has, with the same names, each inside the
 * KozmosThemeProvider the Storybook's decorator gives every story. React's
 * are drawn by their own renders, and so are these;
 * test/parity/tag.parity.spec.ts holds each to React's server render.
 * Generated by `port Tag`; written by hand.
 */
const meta: Meta<typeof KozmosTag> = {
  title: "Vue/Core/Data display/Tag",
  component: KozmosTag,
};

export default meta;
type Story = StoryObj<typeof KozmosTag>;

export const Default: Story = {
  render: () => ({
    components: { KozmosTag },
    template: `<KozmosTag>Tag</KozmosTag>`,
  }),
};

/**
 * A listener for `remove` draws the remove button. React's story alerts;
 * this one keeps the Tag, so its button can be pressed again and again.
 */
export const Removable: Story = {
  render: () => ({
    components: { KozmosTag },
    setup: () => ({ removed: () => {} }),
    template: `<KozmosTag @remove="removed">Removable Tag</KozmosTag>`,
  }),
};

/**
 * The six emotions, filled and outlined. The product drives this axis on
 * 33,988 tag instances across ten surfaces.
 */
export const Emotions: Story = {
  render: () => ({
    components: { KozmosTag },
    setup: () => ({
      emotions: [
        ["neutral", "Neutral"],
        ["themed", "Themed"],
        ["success", "Open"],
        ["danger", "Closed"],
        ["informative", "Info"],
        ["alert", "Delayed"],
      ],
    }),
    template: `
      <div class="flex flex-col gap-3">
        <div class="flex flex-wrap items-center gap-2">
          <KozmosTag v-for="[emotion, label] in emotions" :key="emotion" :emotion="emotion">{{ label }}</KozmosTag>
        </div>
        <div class="flex flex-wrap items-center gap-2">
          <KozmosTag v-for="[emotion, label] in emotions" :key="emotion" :emotion="emotion" variant="outline">{{ label }}</KozmosTag>
        </div>
      </div>
    `,
  }),
};
